for call in (lambda: db.set('', 1), lambda: db.set('bad', {'': 1}), lambda: db.set('bad', float('inf')), lambda: db.backup('')):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
db.backup('one')
try:
    db.backup('one')
    raise AssertionError('expected ValueError')
except ValueError:
    pass
assert db.get('ok') == 1
for call in (lambda: db.restore('missing'), lambda: db.drop_backup('missing')):
    try:
        call()
        raise AssertionError('expected KeyError')
    except KeyError:
        pass
